R5=[]
def ref5(pmid, typ, systems, mechs, direction, summ):
    a = META[pmid]
    au = a.get('authors') or []
    if not au: raise SystemExit('no authors for '+pmid)
    names = ["%s %s" % (x['last_name'], x.get('initials','')) for x in au[:3]]
    short = ", ".join(names) + (", et al." if len(au) > 3 else "")
    c = a.get('citation') or {}
    cit = (c.get('volume','') + ("(%s)" % c['issue'] if c.get('issue') else "") + (":%s" % c['pages'] if c.get('pages') else "")) if c else ""
    R5.append(dict(pmid=pmid, first_author=au[0]['last_name'], authors_short=short, year=int(a['publication_date']['year']), title=a['title'],
                   journal=a['journal']['iso_abbreviation'], citation=cit, doi=a['identifiers'].get('doi'), pmcid=a['identifiers'].get('pmc'),
                   type=typ, systems=systems, mechs=mechs, direction=direction, summary=summ))
